cd /app && mkdir -p work && python3 - <<'EOF'
import pandas as pd, re
tr=pd.read_parquet('data/train-00000-of-00001.parquet')
te=pd.read_parquet('data/test-00000-of-00001.parquet')
def clean(s):
    return re.sub(r'\s+',' ',str(s)).strip()
# split for tuning
val=tr.sample(n=30000, random_state=42)
fit=tr.drop(val.index)
with open('work/fit.txt','w',encoding='utf-8') as f:
    for y,t in zip(fit.label,fit.text): f.write(f'__label__{y} {clean(t)}\n')
with open('work/val.txt','w',encoding='utf-8') as f:
    for y,t in zip(val.label,val.text): f.write(f'__label__{y} {clean(t)}\n')
with open('work/test.txt','w',encoding='utf-8') as f:
    for y,t in zip(te.label,te.text): f.write(f'__label__{y} {clean(t)}\n')
with open('work/all.txt','w',encoding='utf-8') as f:
    for y,t in zip(tr.label,tr.text): f.write(f'__label__{y} {clean(t)}\n')
print('done', len(fit), len(val), len(te))
EOF
ls -lh work/

